css:
.void-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  filter: url("#goo");
  margin-top: 60px;
}

.void-wrapper .singularity {
  position: absolute;
  bottom: 50px;
  width: 60px;
  height: 60px;
  background: #000;
  border-radius: 50%;
  opacity: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  transform: translateY(40px) scale(0.1);
}

.void-wrapper .content {
  opacity: 0;
  transition: 0.3s;
  color: #fff;
  font-family: "Syncopate", sans-serif;
  font-size: 0.7rem;
  letter-spacing: 4px;
  text-shadow: 0 0 10px #fff;
}

.void-wrapper .event-horizon {
  position: relative;
  z-index: 2;
  padding: 20px 40px;
  background: #000;
  color: #fff;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-family: "Syncopate", sans-serif;
  font-weight: 900;
  letter-spacing: 2px;
  transition: 0.3s;
  box-shadow: 0 0 0px rgba(255, 255, 255, 0);
}

.void-wrapper:hover .singularity {
  opacity: 1;
  width: 180px;
  height: 80px;
  border-radius: 20px;
  transform: translateY(-60px) scale(1);
}

.void-wrapper:hover .content {
  opacity: 1;
  transition-delay: 0.4s;
}

.void-wrapper:hover .event-horizon {
  box-shadow: 0 0 30px rgba(255, 255, 255, 0.2);
  transform: scale(0.95);
  letter-spacing: 6px;
}

.void-wrapper .singularity::before {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: inherit;
  background: linear-gradient(45deg, #ff00ff, #00ffff, #ff00ff);
  z-index: -1;
  filter: blur(10px);
  animation: rotate 2s linear infinite;
  opacity: 0;
  transition: 0.5s;
}

.void-wrapper:hover .singularity::before {
  opacity: 0.7;
}

@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
